#!/usr/bin/env python3
"""Independent double scalar transcription of the pinned Filament AgX source.

Regenerate only on an explicit source-contract change. This script never reads
PPR shader code. It emits frozen C++ initializer rows used by the independent post fixtures
fixture, not a runtime dependency. Inputs round through binary16 scene storage.
"""
# Copyright (C) 2020 The Android Open Source Project (color space constants)
# Copyright (C) 2021 The Android Open Source Project (AgxToneMapper)
# Licensed under the Apache License, Version 2.0; see LICENSE in this directory.

import math
from pathlib import Path
import struct

PIN = "fd9ec7ff9510df148011c5326bcb50d4bfb811ca"

# These are COLUMNS, preserving the upstream mat3f constructor convention.
SRGB_XYZ = ((.4124560,.2126730,.0193339),(.3575760,.7151520,.1191920),(.1804380,.0721750,.9503040))
XYZ_REC2020 = ((1.7166634,-.6666738,.0176425),(-.3556733,1.6164557,-.0427770),(-.2533681,.0157683,.9422433))
REC2020_XYZ = ((.6369530,.2626983,0.),(.1446169,.6780088,.0280731),(.1688558,.0592929,1.0608272))
XYZ_SRGB = ((3.2404542,-.9692660,.0556434),(-1.5371385,1.8760108,-.2040259),(-.4985314,.0415560,1.0572252))
INSET = ((.856627153315983,.137318972929847,.11189821299995),
         (.0951212405381588,.761241990602591,.0767994186031903),
         (.0482516061458583,.101439036467562,.811302368396859))
OUTSET_INV = ((.899796955911611,.11142098895748,.11142098895748),
              (.0871996192028351,.875575586156966,.0871996192028349),
              (.013003424885555,.0130034248855548,.801379391839686))


def multiply(columns, vector):
    return [sum(columns[column][row]*vector[column] for column in range(3)) for row in range(3)]


def inverse(columns):
    # Independent double Gauss-Jordan inverse of upstream AgXOutsetMatrixInv.
    rows = [[columns[column][row] for column in range(3)]+[float(row==column) for column in range(3)] for row in range(3)]
    for column in range(3):
        pivot = max(range(column,3),key=lambda row: abs(rows[row][column]))
        rows[pivot],rows[column] = rows[column],rows[pivot]
        divisor = rows[column][column]
        rows[column] = [value/divisor for value in rows[column]]
        for row in range(3):
            if row==column:
                continue
            factor = rows[row][column]
            rows[row] = [value-factor*base for value,base in zip(rows[row],rows[column])]
    return tuple(tuple(rows[row][column+3] for row in range(3)) for column in range(3))


def agx_punchy(rgb, ev):
    v = [max(struct.unpack('e',struct.pack('e',value))[0],0.)*2.**ev for value in rgb]
    v = multiply(XYZ_REC2020,multiply(SRGB_XYZ,v))
    v = multiply(INSET,[max(value,0.) for value in v])
    x = [max(0.,min(1.,(math.log2(max(value,1.e-10))+12.47393)/(4.026069+12.47393))) for value in v]
    # Preserve the original polynomial evaluation rather than importing the shader.
    v = [-17.86*t**7+78.01*t**6-126.7*t**5+92.06*t**4-28.72*t**3+4.361*t*t-.1718*t+.002857 for t in x]
    luma = sum(a*b for a,b in zip(v,(.2126,.7152,.0722)))
    v = [luma+1.4*(value**1.35-luma) for value in v]
    v = [max(value,0.)**2.2 for value in multiply(inverse(OUTSET_INV),v)]
    return [max(0.,min(1.,value)) for value in multiply(XYZ_SRGB,multiply(REC2020_XYZ,v))]


def main():
    patches = [(0.,0.,0.),(-1.,-.5,-.25),(.18,.18,.18),(1.,1.,1.),
               (1.,0.,0.),(0.,1.,0.),(0.,0.,1.),(16.,.25,32.),
               (.125,16.,32.),(32.,8.,.25),(-.5,1.,4.),(65504.,0.,0.),
               (65504.,65504.,65504.),(2.**-12,)*3,(.5,1.,2.),(1.,2.,4.)]
    patches += [(2.**(index-24),)*3 for index in range(16,32)]
    rows = [f"// Generated by generate_goldens.py from Filament {PIN}; do not hand edit."]
    for rgb in patches:
        outputs = [agx_punchy(rgb,ev) for ev in (0.,1.,-16.,16.)]
        array = lambda values: "{"+", ".join(format(value,'.17g') for value in values)+"}"
        rows.append("{"+array(rgb)+", {"+", ".join(array(value) for value in outputs)+"}},")
    Path(__file__).with_name("Golden.inc").write_text("\n".join(rows)+"\n")


if __name__=="__main__":
    main()
